  function filterBar({status=true,channel=false,type=false}={}){return `<div class="ps313-filter" data-ps313-filter><div class="field search"><label>${tr('Search')}</label><input data-f-search placeholder="${tr('Search records…')}"></div>${status?`<div class="field"><label>${tr('Status')}</label><select data-f-status><option value="">${tr('All Statuses')}</option></select></div>`:''}${channel?`<div class="field"><label>${tr('Sales Channel')}</label><select data-f-channel><option value="">${tr('All Channels')}</option></select></div>`:''}${type?`<div class="field"><label>${tr('Type')}</label><select data-f-type><option value="">${tr('All Types')}</option></select></div>`:''}<div class="field"><label>${tr('Sort By')}</label><select data-f-sort></select></div><div class="field"><label>${tr('Order')}</label><select data-f-dir><option value="asc">${tr('Ascending')}</option><option value="desc" selected>${tr('Descending')}</option></select></div><button type="button" class="btn" data-f-clear>${tr('Clear Filters')}</button></div>`}

  function wireTableFilters(host){
    const bar=host?.querySelector('[data-ps313-filter]'),table=host?.querySelector('table');if(!bar||!table)return;
    const rows=[...table.querySelectorAll('tr')].slice(1),heads=[...table.querySelectorAll('tr:first-child th')].map((h,i)=>({i,label:h.textContent.trim()}));
    const sort=bar.querySelector('[data-f-sort]');if(sort)sort.innerHTML=heads.filter(x=>x.label&&x.label!==t('Actions')).map(x=>`<option value="${x.i}">${e(x.label)}</option>`).join('');
    const statusI=heads.find(x=>/status|상태/i.test(x.label))?.i,channelI=heads.find(x=>/channel|채널/i.test(x.label))?.i,typeI=heads.find(x=>/type|유형|분류/i.test(x.label))?.i;
    const fill=(sel,idx)=>{if(!sel||idx==null)return;const vals=[...new Set(rows.map(r=>r.children[idx]?.textContent.trim()).filter(Boolean))].sort();sel.innerHTML=sel.innerHTML.split('</option>')[0]+'</option>'+vals.map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('')};fill(bar.querySelector('[data-f-status]'),statusI);fill(bar.querySelector('[data-f-channel]'),channelI);fill(bar.querySelector('[data-f-type]'),typeI);
    const apply=()=>{const q=(bar.querySelector('[data-f-search]')?.value||'').toLowerCase(),sv=bar.querySelector('[data-f-status]')?.value||'',cv=bar.querySelector('[data-f-channel]')?.value||'',tv=bar.querySelector('[data-f-type]')?.value||'';for(const r of rows){const cells=[...r.children];r.style.display=(!q||r.textContent.toLowerCase().includes(q))&&(!sv||cells[statusI]?.textContent.trim()===sv)&&(!cv||cells[channelI]?.textContent.trim()===cv)&&(!tv||cells[typeI]?.textContent.trim()===tv)?'':'none'}const idx=Number(sort?.value||0),dir=bar.querySelector('[data-f-dir]')?.value==='asc'?1:-1,tbody=table.tBodies[0]||table;rows.sort((a,b)=>{const av=a.children[idx]?.textContent.trim()||'',bv=b.children[idx]?.textContent.trim()||'',an=Number(av.replace(/[^0-9.-]/g,'')),bn=Number(bv.replace(/[^0-9.-]/g,''));return ((Number.isFinite(an)&&Number.isFinite(bn)&&av.match(/\d/)&&bv.match(/\d/))?an-bn:av.localeCompare(bv))*dir}).forEach(r=>tbody.appendChild(r))};
    bar.querySelectorAll('input,select').forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',apply));bar.querySelector('[data-f-clear]')?.addEventListener('click',()=>{bar.querySelectorAll('input').forEach(x=>x.value='');bar.querySelectorAll('select').forEach(x=>x.selectedIndex=0);const d=bar.querySelector('[data-f-dir]');if(d)d.value='desc';apply()});apply();
  }
  function enhanceGenericList(){
    const c=document.getElementById('content');if(!c||c.querySelector('[data-ps313-generic]'))return;const table=c.querySelector('.table-wrap table, table.table');if(!table)return;const card=table.closest('.card')||table.parentElement;if(!card)return;const marker=document.createElement('div');marker.dataset.ps313Generic='1';marker.innerHTML=filterBar();card.insertBefore(marker,card.firstChild);wireTableFilters(card);translateElement(marker);
  }
  function enhancePackaging(){
    const c=document.getElementById('content'),grid=c?.querySelector('.ps-pack-grid');if(!grid||c.querySelector('[data-ps313-packfilter]'))return;const wrap=document.createElement('div');wrap.dataset.ps313Packfilter='1';wrap.className='ps313-filter';wrap.innerHTML=`<div class="field search"><label>${tr('Search')}</label><input data-q placeholder="${tr('Search records…')}"></div><div class="field"><label>${tr('Stock State')}</label><select data-stock><option value="">${tr('All Stock States')}</option><option value="in">${tr('In Stock')}</option><option value="low">${tr('Low Stock')}</option><option value="zero">${tr('Out of Stock')}</option></select></div><div class="field"><label>${tr('Sort By')}</label><select data-sort><option value="name">${tr('Name')}</option><option value="stock">${tr('Available Quantity')}</option></select></div><button class="btn" type="button" data-clear>${tr('Clear Filters')}</button>`;grid.parentElement.insertBefore(wrap,grid);const apply=()=>{const q=(wrap.querySelector('[data-q]').value||'').toLowerCase(),st=wrap.querySelector('[data-stock]').value,cards=[...grid.children];for(const x of cards){const cls=x.classList.contains('zero')?'zero':x.classList.contains('low')?'low':'in';x.style.display=(!q||x.textContent.toLowerCase().includes(q))&&(!st||cls===st)?'':'none'}const sort=wrap.querySelector('[data-sort]').value;cards.sort((a,b)=>sort==='name'?(a.querySelector('h3')?.textContent||'').localeCompare(b.querySelector('h3')?.textContent||''):Number((b.textContent.match(/Available Quantity\s*([\d,.]+)/i)||[])[1]?.replaceAll(',','')||0)-Number((a.textContent.match(/Available Quantity\s*([\d,.]+)/i)||[])[1]?.replaceAll(',','')||0)).forEach(x=>grid.appendChild(x))};wrap.querySelectorAll('input,select').forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',apply));wrap.querySelector('[data-clear]').onclick=()=>{wrap.querySelector('input').value='';wrap.querySelectorAll('select').forEach(x=>x.selectedIndex=0);apply()};translateElement(wrap);apply();
  }

