  window.psCompleteOrder313=async function(id){if(!await confirmAction({title:'Complete Order',message:'Complete this reserved order and release the finished stock to the sale?',confirmLabel:'Complete Order'}))return;await api(`/api/pink-salt/orders/${id}/complete-v313`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(t('Order completed'));closeModal();if(view==='psSales')loadView()};

  window.psSaleForm313=async function(){const [customers,products]=await Promise.all([api('/api/pink-salt/customers-v313'),api('/api/pink-salt/products')]);window.__ps313Customers=customers.filter(x=>x.active);window.__ps313ProductsSale=products.filter(x=>x.active&&Number(x.available_units||0)>0);window.__ps313Lines=[{product_id:'',quantity_units:1,unit_price_krw:'',suggested_price_krw:0,pricing_source:'',price_override_reason:''}];modal(`<h2>${tr('New Sale / Order')}</h2><p class="muted">${tr('Customer-specific price → pricing tier → product default → authorized manual override.')}</p><form onsubmit="psSaveSale313(event)"><div class="grid g4"><div class="field"><label>${tr('Order Date')}</label><input name="order_date" type="date" value="${iso()}" onchange="ps313RepriceAll()" required></div><div class="field"><label>${tr('Customer / Store')}</label><select name="customer_id" onchange="ps313CustomerChanged(this.form)"><option value="">${tr('Walk-in / Direct')}</option>${window.__ps313Customers.map(x=>`<option value="${x.id}">${e(x.name)}</option>`).join('')}</select></div><div class="field"><label>${tr('Sales Channel')}</label><input name="sales_channel" value="Direct" required></div><div class="field"><label>${tr('Order Type')}</label><select name="order_type"><option value="Retail">${tr('Retail')}</option><option value="Wholesale">${tr('Wholesale')}</option><option value="Corporate / Gift">${tr('Corporate / Gift')}</option></select></div></div><div class="grid g3"><div class="field"><label>${tr('Order Status')}</label><select name="order_status" onchange="ps313OrderStatusChanged(this.form)"><option value="Completed">${tr('Complete Sale Now')}</option><option value="Reserved">${tr('Reserve Order')}</option></select></div><div class="field"><label>${tr('Credit Terms (Days)')}</label><input name="credit_terms_days" type="number" min="0" step="1" value="0"></div><div class="field"><label>${tr('Due Date')}</label><input name="due_date" type="date"><div class="ps313-price-note">${tr('Use customer terms')}</div></div></div><div id="ps313CreditApply" class="card" style="display:none;margin:10px 0;padding:12px"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><b>${tr('Available Customer Credit')}</b><strong id="ps313CreditAmount">₩0</strong></div><label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px"><input type="checkbox" name="apply_available_credit" value="1" style="width:auto;margin-top:3px"><span>${tr('Apply available credit to this order after completion')}</span></label><div class="ps313-price-note">${tr('Credit is allocated from the customer’s oldest unallocated receipts and cannot exceed the order outstanding.')}</div></div><div class="field"><label>${tr('Order Lines')}</label><div id="ps313OrderLines"></div><button type="button" class="btn small" onclick="ps313AddLine()">+ ${tr('Add Product')}</button></div><div class="grid g4"><div class="field"><label>${tr('Discount')}</label><input name="discount_krw" type="number" min="0" step="1" value="0"></div><div class="field"><label>${tr('Delivery Fee')}</label><input name="delivery_fee_krw" type="number" min="0" step="1" value="0"></div><div class="field"><label>${tr('Platform Fee')}</label><input name="platform_fee_krw" type="number" min="0" step="1" value="0"><div class="ps313-price-note">${tr('Estimated')}</div></div><div class="field"><label>${tr('Payment Status')}</label><select name="payment_status" onchange="ps313PaidChanged(this.form)"><option value="Pending">${tr('Unpaid')}</option><option value="Paid">${tr('Paid')}</option></select></div></div><div id="ps313PaidFields" style="display:none"><div class="grid g3"><div class="field"><label>${tr('Payment Method')}</label><select name="payment_method"><option value="Bank">${tr('Bank')}</option><option value="Cash">${tr('Cash')}</option><option value="Card">${tr('Card')}</option><option value="Marketplace Settlement">${tr('Marketplace Settlement')}</option></select></div><div class="field"><label>${tr('Payment Reference')}</label><input name="reference"></div><div class="field"><label>${tr('Payment Receipt / Evidence')}</label><input name="receipt" type="file"></div></div></div><div class="field"><label>${tr('Notes')}</label><textarea name="notes"></textarea></div><p class="muted">${tr('Price cannot be below current cost without CEO / Owner authorization.')}</p><div class="actions"><button type="button" class="btn" onclick="closeModal()">${tr('Cancel')}</button><button class="btn primary">${tr('Save')}</button></div></form>`, 'wide');ps313DrawLines();ps313RefreshCreditBox(document.querySelector('#modalRoot form'));translateElement(document.getElementById('modalRoot'))};
  window.ps313DrawLines=function(){const host=document.getElementById('ps313OrderLines'),products=window.__ps313ProductsSale||[];if(!host)return;host.innerHTML=(window.__ps313Lines||[]).map((x,i)=>`<div class="ps313-order-line"><div class="field"><label>${tr('Finished Product')}</label><select onchange="ps313LineChanged(${i},'product_id',this.value)"><option value="">—</option>${products.map(p=>`<option value="${p.id}" ${String(p.id)===String(x.product_id)?'selected':''}>${e(p.sku)} · ${e(p.name)} · ${qty(p.available_units)} ${tr('Available')}</option>`).join('')}</select></div><div class="field"><label>${tr('Quantity')}</label><input type="number" min="1" step="1" value="${Number(x.quantity_units||1)}" onchange="ps313LineChanged(${i},'quantity_units',this.value)"></div><div class="field"><label>${tr('Suggested Price')}</label><input value="${Number(x.suggested_price_krw||0)}" readonly><div class="ps313-price-note">${tr(x.pricing_source||'Product Default')}</div></div><div class="field"><label>${tr('Actual Unit Price')}</label><input type="number" min="0" step="1" value="${x.unit_price_krw===''?'':Number(x.unit_price_krw||0)}" onchange="ps313LineChanged(${i},'unit_price_krw',this.value)"></div><div class="field"><label>${tr('Override Reason')}</label><input value="${e(x.price_override_reason||'')}" onchange="ps313LineChanged(${i},'price_override_reason',this.value)" placeholder="${tr('Required for manual price changes')}"></div><button type="button" class="btn small ps313-remove" onclick="ps313RemoveLine(${i})">×</button></div>`).join('');translateElement(host)};
  window.ps313AddLine=function(){window.__ps313Lines.push({product_id:'',quantity_units:1,unit_price_krw:'',suggested_price_krw:0,pricing_source:'',price_override_reason:''});ps313DrawLines()};window.ps313RemoveLine=function(i){if(window.__ps313Lines.length<=1)return;window.__ps313Lines.splice(i,1);ps313DrawLines()};
  window.ps313LineChanged=async function(i,k,v){const x=window.__ps313Lines[i];if(!x)return;x[k]=k==='quantity_units'?Math.max(1,Math.trunc(Number(v||1))):v;if(k==='product_id'||k==='quantity_units')await ps313PriceLine(i);else ps313DrawLines()};
  window.ps313PriceLine=async function(i){const x=window.__ps313Lines[i],f=document.querySelector('#modalRoot form');if(!x?.product_id||!f)return;const q=new URLSearchParams({product_id:x.product_id,quantity:x.quantity_units||1,date:f.order_date.value||iso()});if(f.customer_id.value)q.set('customer_id',f.customer_id.value);const p=await api('/api/pink-salt/pricing-v313/context?'+q.toString());x.suggested_price_krw=Number(p.unit_price_krw||0);x.unit_price_krw=x.suggested_price_krw;x.pricing_source=p.pricing_source;x.price_override_reason='';ps313DrawLines()};
  window.ps313RepriceAll=async function(){for(let i=0;i<(window.__ps313Lines||[]).length;i++)if(window.__ps313Lines[i].product_id)await ps313PriceLine(i)};
  window.ps313RefreshCreditBox=function(f){const c=(window.__ps313Customers||[]).find(x=>String(x.id)===String(f.customer_id.value)),box=document.getElementById('ps313CreditApply'),amount=document.getElementById('ps313CreditAmount'),cb=f.querySelector('[name="apply_available_credit"]'),available=Math.max(0,Number(c?.unallocated_credit_krw||0)),eligible=!!c&&available>0.005&&f.order_status.value==='Completed'&&f.payment_status.value!=='Paid';if(amount)amount.textContent=fmt(available);if(box)box.style.display=eligible?'':'none';if(cb){cb.disabled=!eligible;if(!eligible)cb.checked=false}};
  window.ps313OrderStatusChanged=function(f){ps313RefreshCreditBox(f)};
  window.ps313CustomerChanged=async function(f){const c=(window.__ps313Customers||[]).find(x=>String(x.id)===String(f.customer_id.value));if(c){f.sales_channel.value=c.sales_channel||'Direct';f.credit_terms_days.value=Number(c.credit_terms_days||0)}else{f.sales_channel.value='Direct';f.credit_terms_days.value=0}ps313RefreshCreditBox(f);await ps313RepriceAll()};
  window.ps313PaidChanged=function(f){const paid=f.payment_status.value==='Paid',box=document.getElementById('ps313PaidFields');if(box)box.style.display=paid?'':'none';f.reference.required=paid;f.receipt.required=paid;ps313RefreshCreditBox(f)};
  window.psSaveSale313=async function(ev){ev.preventDefault();const f=ev.target,lines=window.__ps313Lines||[];if(!lines.length||lines.some(x=>!x.product_id||Number(x.quantity_units||0)<=0))return toast(t('Add at least one finished product to the order.'));for(const x of lines){if(Math.abs(Number(x.unit_price_krw||0)-Number(x.suggested_price_krw||0))>0.005&&!String(x.price_override_reason||'').trim())return toast(t('Manual price override reason is required.'))}if(f.payment_status.value==='Paid'&&(!f.customer_id.value||!f.reference.value.trim()||!f.receipt.files?.length))return toast(t('Customer / store, payment reference and evidence are required for a paid order.'));const fd=new FormData(f);fd.append('items',JSON.stringify(lines.map(x=>({product_id:Number(x.product_id),quantity_units:Number(x.quantity_units),unit_price_krw:Number(x.unit_price_krw),price_override_reason:x.price_override_reason||''}))));await api('/api/pink-salt/orders-v313',{method:'POST',body:fd});closeModal();toast(t('Sale saved'));if(view==='psSales')loadView()};

  const oldLoad=window.loadView;
  window.loadView=async function(){
    if(psSelected()&&view==='psCustomers'){const c=document.getElementById('content');c.innerHTML='<div class="card">Loading…</div>';try{return await customers313(c)}catch(err){c.innerHTML=`<div class="card"><b>${tr('Error')}</b><p class="muted">${e(err.message)}</p><button class="btn primary" onclick="loadView()">${tr('Retry')}</button></div>`;return}}
    if(psSelected()&&view==='psSales'){const c=document.getElementById('content');c.innerHTML='<div class="card">Loading…</div>';try{return await sales313(c)}catch(err){c.innerHTML=`<div class="card"><b>${tr('Error')}</b><p class="muted">${e(err.message)}</p><button class="btn primary" onclick="loadView()">${tr('Retry')}</button></div>`;return}}
    const out=await oldLoad();if(psSelected()&&['psImports','psRawStock','psProduction','psFinished','psWaste'].includes(view))setTimeout(enhanceGenericList,0);if(psSelected()&&view==='psPackaging')setTimeout(enhancePackaging,0);if(psSelected()&&view==='dashboard')setTimeout(async()=>{try{const d=await api('/api/pink-salt/dashboard-v313'),cards=[...document.querySelectorAll('#content .ps-kpi')];for(const card of cards){const lab=card.querySelector('.label')?.textContent||'';if(/Customer Receivables|고객 미수금/.test(lab))card.querySelector('.value').textContent=fmt(d.customer_receivables_krw);if(/Customer Payments Received|고객 결제 수령/.test(lab))card.querySelector('.value').textContent=fmt(d.month_customer_receipts_krw)}}catch(_){ }},0);return out;
  };
  setTimeout(()=>{try{if(psSelected()&&['psImports','psRawStock','psProduction','psFinished','psPackaging','psWaste'].includes(view))loadView()}catch(_){ }},0);
